<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { useUsersStore } from '@/stores/users'
const route = useRoute(), router = useRouter(), store = useUsersStore(), limit = 10
const page = computed(() => Math.max(1, Number(route.query.page) || 1)); const search = ref(String(route.query.q || '')); const pages = computed(() => Math.max(1, Math.ceil(store.total / limit))); let timer = 0
async function load() { await store.fetchUsers(page.value, String(route.query.q || ''), limit) }
function setPage(value: number) { router.push({ query: { ...route.query, page: value } }) }
function onSearch() { window.clearTimeout(timer); timer = window.setTimeout(() => router.replace({ query: { page: 1, ...(search.value.trim() ? { q: search.value.trim() } : {}) } }), 350) }
async function remove(id: number) { if (confirm('Видалити користувача?')) await store.remove(id) }
watch(() => route.query, load); onMounted(load)
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">DUMMYJSON API</p><h1>Користувачі</h1></div><RouterLink class="btn btn-primary" to="/users/new">+ Додати</RouterLink></div><input v-model="search" class="form-control search" placeholder="Пошук користувачів…" @input="onSearch"><div v-if="store.loading" class="status">Завантаження…</div><div v-else-if="store.error" class="alert alert-danger">{{ store.error }}</div><div v-else class="table-wrap"><table><thead><tr><th>Користувач</th><th>Username</th><th>Телефон</th><th></th></tr></thead><tbody><tr v-for="user in store.users" :key="user.id"><td><div class="person"><img :src="user.image" alt=""><span><b>{{ user.firstName }} {{ user.lastName }}</b><small>{{ user.email }}</small></span></div></td><td>@{{ user.username }}</td><td>{{ user.phone }}</td><td class="actions"><RouterLink :to="`/users/${user.id}`">Відкрити</RouterLink><button @click="remove(user.id)">Видалити</button></td></tr></tbody></table></div><div class="pagination"><button :disabled="page <= 1" @click="setPage(page - 1)">←</button><span>Сторінка {{ page }} з {{ pages }}</span><button :disabled="page >= pages" @click="setPage(page + 1)">→</button></div></section></template>
